   876  static void test_store_data(const uint8_t *data, size_t size)
   877  {
   878          CK_SESSION_HANDLE session;
   879          CK_OBJECT_HANDLE  data_obj;
   880          CK_OBJECT_CLASS   class = CKO_DATA;
   881          uint8_t           login_type = CKU_USER;
   882          unsigned char     contents[5001];
   883          int               contents_len = 0;
   884          const uint8_t    *ptr = NULL;
   885          CK_ATTRIBUTE     *data_templ = NULL;
   886          int               n_data_attr = 0;
   887          char             *pin = NULL;
   888          unsigned char     app_id[256];
   889          int               app_id_len = 0;
   890
   891          /* Create data template */
   892          if (!(data_templ = malloc(20 * sizeof(CK_ATTRIBUTE))))
   893                  return;
   894          memset(data_templ, 0, 20 * sizeof(CK_ATTRIBUTE));
   895
   896          /* Get PIN */
   897          if (!(pin = extract_word(&data, &size)))
   898                  goto end;
   899
   900          /* Extract content from fuzzing input*/
   901          memset(contents, 0, sizeof(contents));
   902          ptr = data;
   903          if ((contents_len = get_buffer(&ptr, size, &data, &size, 5000)) == 0)
   904                  goto end;
   905          memcpy(contents, ptr, contents_len);
   906          contents[contents_len] = '\0';
   907
   908          /* Fill attributes to data template */
   909          if (size < 4)
   910                  goto end;
   911          FILL_ATTR(data_templ[n_data_attr], CKA_CLASS, &class, sizeof(class));
   912          n_data_attr++;
   913          FILL_ATTR(data_templ[n_data_attr], CKA_VALUE, &contents, contents_len);
   914          n_data_attr++;
   915          fill_bool_attr(&data_templ, &n_data_attr, CKA_TOKEN, *data % 2);
   916          data++; size--;
   917          fill_bool_attr(&data_templ, &n_data_attr, CKA_PRIVATE, *data % 2);
   918          data++; size--;
   919
   920          /* Get application id*/
   921          if (data[0] % 2){
   922                  data++; size--;
   923                  ptr = data;
   924                  if ((app_id_len = get_buffer(&ptr, size, &data, &size, 256)) == 0)
   925                          goto end;
   926                  memcpy(app_id, ptr, app_id_len);
   927                  FILL_ATTR(data_templ[n_data_attr], CKA_OBJECT_ID, app_id, app_id_len);
   928                  n_data_attr++;
   929          }
   930

930
   931          /* Initialize */
   932          if (fuzz_pkcs11_initialize(data, size, NULL, &session) != CKR_OK)
   933                  goto end;
   934
   935          p11->C_Login(session, login_type, (CK_UTF8CHAR *) pin, strlen(pin));
   936          p11->C_CreateObject(session, data_templ, n_data_attr, &data_obj);
   937          p11->C_CloseSession(session);
   938          p11->C_Finalize(NULL);
   939  end:
   940          free(data_templ);
   941          free(pin);
   942  }
