   315  CK_RV attr_extract(CK_ATTRIBUTE_PTR pAttr, void *ptr, size_t * sizep)
   316  {
   317          size_t size;
   318
   319          if (sizep) {
   320                  size = *sizep;
   321                  if (size < pAttr->ulValueLen)
   322                          return CKR_ATTRIBUTE_VALUE_INVALID;
   323                  *sizep = pAttr->ulValueLen;
   324          } else {
   325                  switch (pAttr->type) {
   326                  case CKA_CLASS:
   327                          size = sizeof(CK_OBJECT_CLASS);
   328                          break;
