    93          p11card->reader = reader;
    94          free_p11card = 1;
    95
    96          /* Connect card to reader */
    97          if ((rv = sc_connect_card(reader, &p11card->card)) != SC_SUCCESS) {
    98                  goto fail;
    99          }
