    93      fuzz_get_chunk(reader, &chunk, &chunk_size);
    94
    95      if (chunk_size > SC_MAX_ATR_SIZE)
    96          chunk_size = SC_MAX_ATR_SIZE;
    97      else
    98          reader->atr.len = chunk_size;
    99
