   484  int
   485  sc_asn1_decode_algorithm_id(struct sc_context *ctx, const unsigned char *in,
   486                              size_t len, struct sc_algorithm_id *id,
   487                              int depth)
   488  {
   489          struct sc_asn1_pkcs15_algorithm_info *alg_info = NULL;
   490          struct sc_asn1_entry asn1_alg_id[3];
   491          int r;
   492
   493          LOG_FUNC_CALLED(ctx);
   494          sc_copy_asn1_entry(c_asn1_alg_id, asn1_alg_id);
   495          sc_format_asn1_entry(asn1_alg_id + 0, &id->oid, NULL, 0);
   496
   497          memset(id, 0, sizeof(*id));
   498          r = _sc_asn1_decode(ctx, asn1_alg_id, in, len, &in, &len, 0, depth + 1);
   499          LOG_TEST_RET(ctx, r, "ASN.1 parsing of algo ID failed");
   500
   501          sc_log(ctx, "decoded OID '%s'", sc_dump_oid(&(id->oid)));
   502
   503          /* See if we understand the algorithm, and if we do, check
   504           * whether we know how to decode any additional parameters */
   505          id->algorithm = (unsigned int ) -1;
   506          alg_info = sc_asn1_get_algorithm_info(id);
   507          if (alg_info != NULL) {
   508                  id->algorithm = alg_info->id;
   509                  if (alg_info->decode) {
   510                          if (asn1_alg_id[1].flags & SC_ASN1_PRESENT) {
   511                                  sc_log(ctx, "SC_ASN1_PRESENT was set, so invalid");
   512                                  LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ASN1_OBJECT);
   513                          }
   514                          r = alg_info->decode(ctx, &id->params, in, len, depth);
   515                  }
   516          }
   517
   518          LOG_FUNC_RETURN(ctx, r);
   519  }
